mapper.select:
SELECT pq.* FROM edu_paper_question pq
WHERE pq.paper_question_paper_id = #{paperId}
ORDER BY pq.paper_question_order ASC

mapper.delete:
DELETE FROM edu_paper_question
WHERE paper_question_paper_id = #{paperId}
  AND paper_question_question_id = #{questionId}

mapper.select:
SELECT pq.* FROM edu_paper_question pq
WHERE pq.paper_question_paper_id = #{paperId}
  AND pq.paper_question_question_id = #{questionId}
LIMIT 1

SELECT pq.* FROM edu_paper_question pq
WHERE pq.paper_question_no = #{questionNo}
LIMIT 1

mapper.update:
UPDATE edu_paper_question
SET paper_question_version = #{version}
WHERE paper_question_paper_id = #{paperId}
